export type Course = {
  id: string;
  level: Level;
  university: string;
  field: string;
  name: string;
  mode: string;
  campuses: string[];
  running: string[];
  onDemand: string[];
  fee: string;
};

export const allCourses: Course[] = PACKED.map((p, i) => ({
  id: `c${i}`,
  level: LEVELS[p[0]],
  university: UNIVERSITIES[p[1]],
  field: FIELDS[p[2]],
  name: p[3],
  mode: p[4] >= 0 ? MODES[p[4]] : "",
  campuses: p[5].map((c) => CAMPUSES[c]),
  running: p[6].map((m) => MONTHS[m]),
  onDemand: p[7].map((m) => MONTHS[m]),
  fee: p[8],
}));

export const courseCounts = {
  total: allCourses.length,
  universities: UNIVERSITIES.length,
  fields: FIELDS.length,
  byLevel: LEVELS.map((l) => ({ level: l, count: allCourses.filter((c) => c.level === l).length })),
  byField: FIELDS.map((f) => ({ field: f, count: allCourses.filter((c) => c.field === f).length }))
    .sort((a, b) => b.count - a.count),
};
